{
  "platform": "react-vite-static",
  "framework": "Vite + React 19",
  "language": "typescript",
  "files": [
    {
      "path": "package.json",
      "language": "json",
      "content": "{
  "name": "meal-planner-ui",
  "private": true,
  "version": "0.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc -b && vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "react": "^19.0.0",
    "react-dom": "^19.0.0"
  },
  "devDependencies": {
    "@vitejs/plugin-react": "^4.3.1",
    "typescript": "^5.5.3",
    "vite": "^5.4.1"
  }
}"
    },
    {
      "path": "vite.config.ts",
      "language": "typescript",
      "content": "import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
});"
    },
    {
      "path": "tsconfig.json",
      "language": "json",
      "content": "{
  "compilerOptions": {
    "target": "ES2020",
    "useDefineForClassFields": true,
    "lib": ["ES2020", "DOM", "DOM.Iterable"],
    "module": "ESNext",
    "skipLibCheck": true,
    "moduleResolution": "bundler",
    "allowImportingTsExtensions": true,
    "resolveJsonModule": true,
    "isolatedModules": true,
    "noEmit": true,
    "jsx": "react-jsx",
    "strict": true,
    "noUnusedLocals": true,
    "noUnusedParameters": true,
    "noFallthroughCasesInSwitch": true
  },
  "include": ["src"]
}"
    },
    {
      "path": "index.html",
      "language": "html",
      "content": "<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Meal Planner</title>
  </head>
  <body>
    <div id="root"></div>
    <script type="module" src="/src/main.tsx"></script>
  </body>
</html>"
    },
    {
      "path": "src/main.tsx",
      "language": "typescript",
      "content": "import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);"
    },
    {
      "path": "src/types.ts",
      "language": "typescript",
      "content": "export interface PlannerInput {
  budget: number;
  familySize: number;
}

export interface MealDay {
  dayName: string;
  mealName: string;
  cost: number;
}

export interface ShoppingItem {
  ingredient: string;
  quantity: string;
  cost: number;
}

export interface PlanResult {
  days: MealDay[];
  shoppingList: ShoppingItem[];
  totalCost: number;
}"
    },
    {
      "path": "src/App.tsx",
      "language": "typescript",
      "content": "import { useState } from 'react';
import { MealPlanner } from './components/MealPlanner';
import { ShoppingList } from './components/ShoppingList';
import { PlanResult } from './types';

export function App() {
  const [result, setResult] = useState<PlanResult | null>(null);

  return (
    <main style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <h1>Weekly Meal Planner</h1>
      <MealPlanner onPlanGenerated={setResult} />
      {result && <ShoppingList result={result} />}
    </main>
  );
}"
    },
    {
      "path": "src/components/MealPlanner.tsx",
      "language": "typescript",
      "content": "import { useState } from 'react';
import { PlanResult } from '../types';

interface Props {
  onPlanGenerated: (result: PlanResult) => void;
}

export function MealPlanner({ onPlanGenerated }: Props) {
  const [budget, setBudget] = useState(120);
  const [familySize, setFamilySize] = useState(4);

  const handleGenerate = () => {
    // TODO(code-dj): Objective - Plan a week of dinners on a $120 budget.
    // TODO(code-dj): Success criteria - Total cost <= budget; 7 distinct meals.
    const stubbedResult: PlanResult = {
      days: [{ dayName: 'Day 1', mealName: 'Spaghetti Bolognese', cost: 15 }],
      shoppingList: [{ ingredient: 'Pasta', quantity: '1 box', cost: 2 }],
      totalCost: 15
    };
    onPlanGenerated(stubbedResult);
  };

  return (
    <section style={{ marginBottom: '2rem' }}>
      <h2>Input Parameters</h2>
      <div style={{ marginBottom: '1rem' }}>
        <label>Budget ($): <input type="number" value={budget} onChange={e => setBudget(Number(e.target.value))} /></label>
      </div>
      <div style={{ marginBottom: '1rem' }}>
        <label>Family Size: <input type="number" value={familySize} onChange={e => setFamilySize(Number(e.target.value))} /></label>
      </div>
      <button onClick={handleGenerate}>Generate Plan</button>
    </section>
  );
}"
    },
    {
      "path": "src/components/ShoppingList.tsx",
      "language": "typescript",
      "content": "import { PlanResult } from '../types';

interface Props {
  result: PlanResult;
}

export function ShoppingList({ result }: Props) {
  return (
    <section>
      <h2>Plan Results</h2>
      <p><strong>Total Cost:</strong> ${result.totalCost.toFixed(2)}</p>

      <h3>Meal Schedule (days[])</h3>
      <ul>
        {result.days.map((d, i) => (
          <li key={i}>{d.dayName}: {d.mealName} (${d.cost.toFixed(2)})</li>
        ))}
      </ul>

      <h3>Shopping List (shoppingList[])</h3>
      <ul>
        {result.shoppingList.map((item, i) => (
          <li key={i}>{item.quantity} {item.ingredient} (${item.cost.toFixed(2)})</li>
        ))}
      </ul>
    </section>
  );
}"
    },
    {
      "path": ".env.example",
      "language": "env",
      "content": "# VITE_RECIPE_API_KEY=your_api_key_here # Example placeholder if external API is used for meals"
    },
    {
      "path": "README.md",
      "language": "markdown",
      "content": "# Meal Planner

Scaffolded MVP to plan a week of dinners on a $120 budget.

## I/O Contract
- **Input**: budget, family size.
- **Output**: days[], shoppingList[].

## Success Criteria
- Total cost <= budget
- 7 distinct meals"
    }
  ],
  "manifest": {
    "framework": "react",
    "language": "typescript",
    "entrypoint": "index.html",
    "installCommand": "pnpm install",
    "runCommand": "pnpm run dev",
    "buildCommand": "pnpm run build",
    "deployTarget": "static"
  },
  "notes": "Scaffolded 11 files mapping I/O inputs to 'MealPlanner' & outputs to 'ShoppingList'. Logic stubbed per PDD constraints."
}

